package com.lims.service;

import com.lims.dao.ManagerCatalogDAO;import com.lims.model.*;import java.math.BigDecimal;import java.util.*;
public class ManagerCatalogService{
 private final ManagerCatalogDAO dao=new ManagerCatalogDAO();private final PurchasingService purchasing=new PurchasingService();private final AuditLogService audit=new AuditLogService();
 public List<Brand> brands(){return dao.brands();}public List<ProductLine> lines(){return dao.lines();}public List<Product> products(){return dao.products();}public Product product(int id){return dao.product(id);}public List<Customer> customers(){return dao.customers();}public Customer customer(int id){return dao.customer(id);}public List<Supplier> suppliers(){return purchasing.getAllSuppliers();}public Supplier supplier(int id){return purchasing.getSupplier(id);}
 public void saveBrand(User a,String id,String name,String status,String ip,String ua){Brand x=new Brand();x.setBrandId(parseOptional(id));x.setBrandName(clean(name));x.setStatus(validStatus(status));if(x.getBrandName().isEmpty()||x.getBrandName().length()>100)throw new IllegalArgumentException("Tên thương hiệu bắt buộc, tối đa 100 ký tự.");if(!dao.saveBrand(x))throw new IllegalStateException("Không lưu được thương hiệu; tên có thể đã tồn tại.");audit.logAction(a.getUserId(),a.getUsername(),x.getBrandId()==0?"CREATE":"UPDATE","BRANDS",x.getBrandName(),null,Map.of("name",x.getBrandName(),"status",x.getStatus()),ip,ua);}
 public void deleteBrand(User a,String value,String ip,String ua){int id=positive(value);if(!dao.deleteBrand(id))throw new IllegalStateException("Không thể xóa thương hiệu đang được dòng máy sử dụng.");audit.logAction(a.getUserId(),a.getUsername(),"DELETE","BRANDS",String.valueOf(id),null,null,ip,ua);}
 public void saveLine(User a,String id,String brand,String name,String status,String ip,String ua){ProductLine x=new ProductLine();x.setProductLineId(parseOptional(id));x.setBrandId(positive(brand));x.setLineName(clean(name));x.setStatus(validStatus(status));if(x.getLineName().isEmpty()||x.getLineName().length()>100)throw new IllegalArgumentException("Tên dòng máy bắt buộc, tối đa 100 ký tự.");if(dao.brands().stream().noneMatch(b->b.getBrandId()==x.getBrandId()))throw new IllegalArgumentException("Thương hiệu không tồn tại.");if(!dao.saveLine(x))throw new IllegalStateException("Không lưu được dòng máy.");audit.logAction(a.getUserId(),a.getUsername(),x.getProductLineId()==0?"CREATE":"UPDATE","PRODUCT_LINES",String.valueOf(x.getProductLineId()),null,Map.of("brandId",x.getBrandId(),"lineName",x.getLineName(),"status",x.getStatus()),ip,ua);}
 public void setLineStatus(User a,String value,String status,String ip,String ua){int id=positive(value);String s=validStatus(status);if(!dao.setLineStatus(id,s))throw new IllegalStateException("Không cập nhật được trạng thái dòng máy.");audit.logAction(a.getUserId(),a.getUsername(),"UPDATE","PRODUCT_LINES",String.valueOf(id),null,Map.of("status",s),ip,ua);}
 public void saveProduct(User a,Product x,String ip,String ua){x.setProductCode(clean(x.getProductCode()));x.setProductName(clean(x.getProductName()));x.setCpu(clean(x.getCpu()));x.setRam(clean(x.getRam()));x.setStorage(clean(x.getStorage()));x.setGpu(clean(x.getGpu()));x.setScreen(clean(x.getScreen()));x.setStatus(validProductStatus(x.getStatus()));if(x.getProductCode().isEmpty()||x.getProductCode().length()>50||x.getProductName().isEmpty()||x.getProductName().length()>150)throw new IllegalArgumentException("Mã model bắt buộc tối đa 50 ký tự; tên model tối đa 150 ký tự.");if(x.getCpu().isEmpty()||x.getCpu().length()>100||x.getRam().isEmpty()||x.getRam().length()>50||x.getStorage().isEmpty()||x.getStorage().length()>100||x.getGpu().length()>100||x.getScreen().length()>50)throw new IllegalArgumentException("Cấu hình CPU/RAM/SSD bắt buộc và phải đúng giới hạn ký tự.");if(dao.lines().stream().noneMatch(l->l.getProductLineId()==x.getProductLineId()&&"ACTIVE".equals(l.getStatus())))throw new IllegalArgumentException("Chọn dòng máy đang hoạt động.");if(x.getUnitPrice()==null||x.getUnitPrice().signum()<=0||x.getUnitPrice().scale()>2||x.getUnitPrice().precision()>18)throw new IllegalArgumentException("Giá bán phải lớn hơn 0, tối đa 2 chữ số thập phân.");int oldId=x.getProductId();if(!dao.saveProduct(x))throw new IllegalStateException("Không lưu được model; mã sản phẩm có thể đã tồn tại.");audit.logAction(a.getUserId(),a.getUsername(),oldId==0?"CREATE":"UPDATE","PRODUCTS",String.valueOf(x.getProductId()),null,productSummary(x),ip,ua);}
 public void deactivateProduct(User a,String value,String ip,String ua){int id=positive(value);if(!dao.deactivateProduct(id))throw new IllegalStateException("Không cập nhật được model.");audit.logAction(a.getUserId(),a.getUsername(),"DEACTIVATE","PRODUCTS",String.valueOf(id),null,Map.of("status","INACTIVE"),ip,ua);}
 public void saveCustomer(User a,Customer x,String ip,String ua){x.setCustomerName(clean(x.getCustomerName()));x.setPhone(clean(x.getPhone()));x.setEmail(clean(x.getEmail()));x.setAddress(clean(x.getAddress()));x.setStatus(validStatus(x.getStatus()));if(x.getCustomerName().isEmpty()||x.getCustomerName().length()>150||x.getPhone().isEmpty()||x.getPhone().length()>20||x.getEmail().length()>100||x.getAddress().length()>255)throw new IllegalArgumentException("Tên khách hàng và số điện thoại bắt buộc; kiểm tra giới hạn độ dài.");if(!x.getEmail().isEmpty()&&!x.getEmail().matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new IllegalArgumentException("Email khách hàng không hợp lệ.");int id=x.getCustomerId();if(!dao.saveCustomer(x))throw new IllegalStateException("Không lưu được hồ sơ khách hàng.");audit.logAction(a.getUserId(),a.getUsername(),id==0?"CREATE":"UPDATE","CUSTOMERS",String.valueOf(x.getCustomerId()),null,customerSummary(x),ip,ua);}
 public void deactivateCustomer(User a,String value,String ip,String ua){int id=positive(value);if(!dao.deactivateCustomer(id))throw new IllegalStateException("Không thể ngừng sử dụng khách hàng.");audit.logAction(a.getUserId(),a.getUsername(),"DEACTIVATE","CUSTOMERS",String.valueOf(id),null,Map.of("status","INACTIVE"),ip,ua);}
 public void saveSupplier(User a,Supplier x,String ip,String ua){purchasing.saveSupplier(a,x,ip,ua);}
 private Object productSummary(Product p){Map<String,Object> m=new LinkedHashMap<>();m.put("code",p.getProductCode());m.put("name",p.getProductName());m.put("lineId",p.getProductLineId());m.put("cpu",p.getCpu());m.put("ram",p.getRam());m.put("storage",p.getStorage());m.put("gpu",p.getGpu());m.put("screen",p.getScreen());m.put("unitPrice",p.getUnitPrice());m.put("status",p.getStatus());return m;}
 private Object customerSummary(Customer c){Map<String,Object> m=new LinkedHashMap<>();m.put("name",c.getCustomerName());m.put("phone",c.getPhone());m.put("email",c.getEmail());m.put("address",c.getAddress());m.put("status",c.getStatus());return m;}
 private String clean(String x){return x==null?"":x.trim();}private String validStatus(String x){String s=x==null?"ACTIVE":x.trim().toUpperCase();if(!Set.of("ACTIVE","INACTIVE").contains(s))throw new IllegalArgumentException("Trạng thái phải là ACTIVE hoặc INACTIVE.");return s;}private String validProductStatus(String x){String s=x==null?"ACTIVE":x.trim().toUpperCase();if(!Set.of("ACTIVE","INACTIVE","DISCONTINUED").contains(s))throw new IllegalArgumentException("Trạng thái model không hợp lệ.");return s;}
 private int positive(String x){int n=parseOptional(x);if(n<1)throw new IllegalArgumentException("Mã dữ liệu không hợp lệ.");return n;}private int parseOptional(String x){if(x==null||x.isBlank())return 0;try{int n=Integer.parseInt(x);if(n<0)throw new NumberFormatException();return n;}catch(Exception e){throw new IllegalArgumentException("Mã dữ liệu không hợp lệ.");}}
}
